+    hasSource: Boolean(response.source_kind),
+    baseUrl: response.base_url ?? '',
+    userId: response.user_id ?? '',
+    systemAccessToken: '',
+    rechargeMultiplier: String(response.recharge_multiplier ?? 1),
+    sync: syncConfigFormFromConfig(response.sync_config),
+  };
