+pub(super) fn candidate_model_ids(
+    globals: &BTreeMap<String, GlobalModelResponse>,
+    bindings: &BTreeMap<String, BindingInfo>,
+    key: &ProviderQuickImportSyncKey,
+    upstream_models: &[UpstreamImportModel],
+) -> Vec<String> {
