+        <Iconify icon="mingcute:close-line" />
+      </IconButton>
+    </Stack>
+  );
+}
+
+function MappingRow({
+  upstreamId,
+  value,
+  models,
+  onChange,
+  onRemove,
+}: {
+  upstreamId: string;
+  value: string;
+  models: GlobalModelResponse[];
+  onChange: (globalId: string) => void;
+  onRemove: () => void;
+}) {
+  const { t } = useTranslate('admin');
+
+  return (
+    <Stack direction={{ xs: 'column', md: 'row' }} spacing={1.5} alignItems={{ md: 'center' }}>
