+pub(super) async fn check_models<I>(
+    importer: &I,
+    source_config: &ProviderQuickImportSourceConfig,
+    key: &ProviderQuickImportSyncKey,
+) -> ProviderResult<ModelCheck>
+where
+    I: UpstreamProviderImportSource,
